"""
============================================================
Topic: Extraction of Indian Cultural Elements Using RAG
============================================================
Author Name(s): Simanta Nandi
Short Description: This project builds a small repository of eight Indian
    literary texts in English (six plain-text files from Project Gutenberg,
    one from Wikisource by way of the Literature of Colonial South Asia
    archive, and one in-copyright book supplied as a text file) and runs them through a retrieval-augmented
    generation (RAG) pipeline in AnythingLLM (Gemma 3 4B served by
    LM Studio). The aim was to pull out the names of Indian flora and
    fauna. The model is small and was trained mostly on Western data, so it
    missed and misread many Indian names. Every name was therefore checked
    by hand against the full source text. The lists below hold only the
    names that survived that check. Each one is traced to an exact
    quotation and its place in the book.
Semester: Monsoon Semester 2026
Affiliation: MA, Digital Humanities and Social Sciences, Department of
    Humanities and Social Sciences, Indian Institute of Technology
    (Indian School of Mines) Dhanbad
============================================================
Licence: Creative Commons Attribution-NonCommercial 4.0 International
         (CC BY-NC 4.0). Seven of the literary texts are public-domain
         editions (Project Gutenberg; Wikisource via scalar.lehigh.edu).
         The Adivasi Will Not Dance (Speaking Tiger, 2015) is in copyright:
         only short quotations from it are given here, for criticism and
         review, and the book itself is not shared.

How to read this file
---------------------
flora_RAG_extraction and fauna_RAG_extraction keep the ten category
labels of the assignment, in the same order. Each label now holds the
verified (and clearly flagged ambiguous) names found across the corpus:

    "<common English name> | as written: <forms in the text> | in: <texts>"

FLORA_FAUNA_BY_TEXT gives the same results text by text.
EVIDENCE holds one record per entity with its exact quotation, location
(section and line number in the cleaned .txt file), status and remarks.
Run `python flora_fauna.py` for a printed summary.

All eight texts were checked against the full source. Generic words
(tree, flower, bird), plant parts, colour words and mythical beings are
left out. The AnythingLLM output for the same texts, with a verdict on
every row, is on the project website.
"""

