 {'text': 'Glimpses of Bengal',
  'name_as_written': 'pán / betel leaf',
  'category': 'Plants',
  'common_english_name': 'Betel leaf (Piper betle), Bengali pán',
  'quotation': 'To him they administer some of this powder, hidden in the usual offering of _pán_[1], and '
               'thus are content to imagine that a portion of the remains of their deceased relative has '
               'gained purifying contact with the sacred water.',
  'location': 'Letter 5: Shazadpur, February 1891 (line 435)',
  'status': 'Verified',
  'occurrences': 2,
  'setting': 'India',
  'paratext_only': False,
  'remarks': 'Kept as _pán_, with the translator\'s footnote "Spices wrapped in betel leaf."'},
 {'text': 'Glimpses of Bengal',
  'name_as_written': 'water-lilies',
  'category': 'Flowers',
  'common_english_name': 'Water lily (Nymphaea sp.)',
  'quotation': 'Through all these the canal, with its gentle current, winds gracefully between its clean, '
               'grassy banks, fringed, in its narrower stretches, with clusters of water-lilies with reeds '
               'growing among them.',
  'location': 'Letter 13: On Board A Canal Steamer Going To Cuttack, August 1891 (line 825)',
  'status': 'Verified',
  'occurrences': 3,
  'setting': 'India',
  'paratext_only': False,
  'remarks': ''},
 {'text': 'Glimpses of Bengal',
  'name_as_written': 'irises',
  'category': 'Flowers',
  'common_english_name': 'Iris',
  'quotation': 'Elsewhere these _beels_ have a peculiar flora and fauna of water-lilies and irises and '
               'various water-fowl.',
  'location': 'Letter 37: Patisar, 13th August 1893 (line 2130)',
  'status': 'Ambiguous',
  'occurrences': 1,
  'setting': 'India',
  'paratext_only': False,
  'remarks': 'A European flower name for a Bengal marsh plant. The real plant (perhaps water hyacinth or a '
             'wild Iris) cannot be told from the text.'},
 {'text': 'Glimpses of Bengal',
  'name_as_written': 'roses',
  'category': 'Flowers',
  'common_english_name': 'Rose',
  'quotation': 'their wilderness of roses, songs of nightingales, wines of Shiraz;',
  'location': 'Letter 48: Shazadpur, 5th September 1894 (line 2587)',
  'status': 'Verified',
  'occurrences': 1,
  'setting': 'Arabian Nights reverie',
  'paratext_only': False,
  'remarks': '"their wilderness of roses" in the Arabian Nights daydream.'},
 {'text': 'Glimpses of Bengal',
  'name_as_written': 'rice-fields / rice / half-ripe rice',
  'category': 'Crops',
  'common_english_name': 'Rice / paddy (Oryza sativa)',
  'quotation': 'Here and there rice-fields, untilled, untended,[1] rise from the moist, clay soil.',
  'location': 'Letter 3: Nearing Shazadpur, January 1891 (line 299)',
  'status': 'Verified',
  'occurrences': 7,
  'setting': 'India',
  'paratext_only': False,
  'remarks': 'The commonest crop in the letters: sown, waving, cut and carried in boats.'},
 {'text': 'Glimpses of Bengal',
  'name_as_written': 'jute',
  'category': 'Crops',
  'common_english_name': 'Jute (Corchorus sp.)',
  'quotation': 'The ferry crosses to and fro, the passers-by with umbrellas up wend their way along the '
               'tow-path, women are washing rice on the split-bamboo trays which they dip in the water, the '
               'ryots are coming to the market with bundles of jute on their heads.',
  'location': 'Letter 35: Shazadpur, 7th July 1893 (line 2068)',
  'status': 'Verified',
  'occurrences': 2,
  'setting': 'India',
  'paratext_only': False,
  'remarks': ''},
 {'text': 'Glimpses of Bengal',
  'name_as_written': 'sugar-cane',
  'category': 'Crops',
  'common_english_name': 'Sugar-cane (Saccharum officinarum)',
  'quotation': 'With rows of villages along its banks, its fields of jute and sugar-cane, its reed patches, '
               'its green bathing slopes, it is like a few lines of a poem, often repeated and as often '
               'enjoyed.',
  'location': 'Letter 57: On The Way To Pabna, 9th July 1895 (line 2938)',
  'status': 'Verified',
  'occurrences': 1,
  'setting': 'India',
  'paratext_only': False,
  'remarks': ''},
 {'text': 'Glimpses of Bengal',
  'name_as_written': 'yam',
  'category': 'Crops',
  'common_english_name': 'Yam leaves (possibly taro, Bengali kochu)',
  'quotation': 'The dripping ryots are crossing the river in the ferryboat, some with their tokas[1] on, '
               'others with yam leaves held over their heads.',
  'location': 'Letter 33: Shelidah, 3rd July 1893 (line 1979)',
  'status': 'Ambiguous',
  'occurrences': 1,
  'setting': 'India',
  'paratext_only': False,
  'remarks': 'Villagers hold "yam leaves" over their heads against rain. In Bengal this use fits taro '
             '(kochu) leaves, so "yam" may be a loose translation.'},
 {'text': 'Glimpses of Bengal',
  'name_as_written': 'melons',
  'category': 'Crops',
  'common_english_name': 'Melon',
  'quotation': 'their narrow bazaar paths with bright overhanging canopies, the men, in loose robes and '
               'multi-coloured turbans, selling dates and nuts and melons;',
  'location': 'Letter 48: Shazadpur, 5th September 1894 (line 2590)',
  'status': 'Verified',
  'occurrences': 1,
  'setting': 'Arabian Nights reverie',
  'paratext_only': False,
  'remarks': ''},
 {'text': 'Glimpses of Bengal',
  'name_as_written': 'corn',
  'category': 'Crops',
  'common_english_name': 'Cereal grain, "corn" (unspecified)',
  'quotation': 'my own consciousness seems to stream through each blade of grass, each sucking root, to rise '
               'with the sap through the trees, to break out with joyous thrills in the waving fields of '
               'corn, in the rustling palm leaves.',
  'location': 'Letter 24: Shelidah, 20th August 1892 (line 1588)',
  'status': 'Ambiguous',
  'occurrences': 1,
  'setting': 'India',
  'paratext_only': False,
  'remarks': 'British "corn": any cereal.'},
 {'text': 'Glimpses of Bengal',
  'name_as_written': 'cotton',
  'category': 'Crops',
  'common_english_name': 'Cotton (Gossypium sp.)',
  'quotation': 'Remnants of clouds cling to the horizon like fluffs of cotton wool.',
  'location': 'Letter 6: On The Way, February 1891 (line 464)',
  'status': 'Verified',
  'occurrences': 2,
  'setting': 'India',
  'paratext_only': False,
  'remarks': 'Named only as cotton wool (a simile) and cloth: a product.'},
 {'text': 'Glimpses of Bengal',
  'name_as_written': 'tobacco',
  'category': 'Crops',
  'common_english_name': 'Tobacco (Nicotiana tabacum)',
  'quotation': "Servants' belongings, an excessively grimy mat, hubble-bubble pipes, tobacco, tinder, and "
               'two wooden chests littered the floor, besides sundry packing-cases full of useless odds and '
               'ends, such as a …',
  'location': 'Letter 2: July 1887 (line 165)',
  'status': 'Verified',
  'occurrences': 1,
  'setting': 'India',
  'paratext_only': False,
  'remarks': 'Named as a smoking product.'},
 {'text': 'Glimpses of Bengal',
  'name_as_written': 'tea',
  'category': 'Crops',
  'common_english_name': 'Tea (Camellia sinensis)',
  'quotation': 'Every one else seemed to be on the opposite shore--the shore of life--where the British '
               'Government and the Nineteenth Century hold sway, and tea and cigarettes.',
  'location': 'Letter 14: Shelidah, October 1891 (line 965)',
  'status': 'Verified',
  'occurrences': 1,
  'setting': 'India',
  'paratext_only': False,
  'remarks': 'Named as a drink.'},
 {'text': 'Glimpses of Bengal',
  'name_as_written': 'cows / calves / cattle / cow',
  'category': 'Mammals',
  'common_english_name': 'Cattle (Bos indicus)',
  'quotation': 'the cows followed, and behind them frisked the calves waving their tails.',
  'location': 'Letter 7: Chuhali, June 1891 (line 486)',
  'status': 'Verified',
  'occurrences': 10,
  'setting': 'India',
  'paratext_only': False,
  'remarks': ''},
 {'text': 'Glimpses of Bengal',
  'name_as_written': 'buffaloes / buffalo',
  'category': 'Mammals',
  'common_english_name': 'Water buffalo (Bubalus bubalis)',
  'quotation': 'Cultivated fields are scarcely to be seen, except where the primitive tribesmen have done a '
               'little ploughing with their buffaloes;',
  'location': 'Letter 25: Boalia, 18th November 1892 (line 1609)',
  'status': 'Verified',
  'occurrences': 4,
  'setting': 'India',
  'paratext_only': False,
  'remarks': ''},
 {'text': 'Glimpses of Bengal',
  'name_as_written': 'elephant / elephants',
  'category': 'Mammals',
  'common_english_name': 'Asian elephant',
  'quotation': 'The elephant is comic, the camel and the giraffe are comic, all overgrowth is comic.',
  'location': 'Letter 14: Shelidah, October 1891 (line 1088)',
  'status': 'Verified',
  'occurrences': 2,
  'setting': 'India',
  'paratext_only': False,
  'remarks': 'Includes Tagore\'s joke that bees are "double-proboscideans".'},
 {'text': 'Glimpses of Bengal',
  'name_as_written': 'dog / canine / pups',
  'category': 'Mammals',
  'common_english_name': 'Dog',
  'quotation': "That is always the gypsies' way: no home anywhere, no landlord to pay rent to, wandering "
               'about as it pleases them with their children, their pigs, and a dog or two;',
  'location': 'Letter 4: Shazadpur, February 1891 (line 351)',
  'status': 'Verified',
  'occurrences': 5,
  'setting': 'India',
  'paratext_only': False,
  'remarks': 'Includes "pups" (a simile) and "canine members of the family".'},
 {'text': 'Glimpses of Bengal',
  'name_as_written': 'pig-sticking / pigs',
  'category': 'Mammals',
  'common_english_name': 'Pig',
  'quotation': 'I asked him over to dinner, but he said he was due elsewhere to arrange for a pig-sticking '
               'party.',
  'location': 'Letter 2: July 1887 (line 149)',
  'status': 'Verified',
  'occurrences': 4,
  'setting': 'India',
  'paratext_only': False,
  'remarks': 'Gypsies\' pigs, plus a British magistrate\'s "pig-sticking" (boar-hunting) party.'},
 {'text': 'Glimpses of Bengal',
  'name_as_written': 'jackal',
  'category': 'Mammals',
  'common_english_name': 'Golden jackal',
  'quotation': '… as I sit up on wakeful nights, with sleeping banks on either side, the silence is broken '
               'only by an occasional cry of a jackal in the woods near some village, or by fragments '
               'undermined by the keen current of the Padma, that tumble from the high cliff-like …',
  'location': 'Letter 19: On The Way To Goalunda, 21st June 1892 (line 1404)',
  'status': 'Verified',
  'occurrences': 1,
  'setting': 'India',
  'paratext_only': False,
  'remarks': ''},
 {'text': 'Glimpses of Bengal',
  'name_as_written': 'squirrels',
  'category': 'Mammals',
  'common_english_name': 'Palm squirrel (Funambulus sp.)',
  'quotation': 'The ticking of the clock on my table, and the pattering of the squirrels which scamper in '
               'and out of my room, are in harmony with all other midday sounds.',
  'location': 'Letter 53: Bolpur, 31st October 1894 (line 2747)',
  'status': 'Verified',
  'occurrences': 2,
  'setting': 'India',
  'paratext_only': False,
  'remarks': '"grey and black striped, furry squirrels": the description fits the Indian palm squirrel.'},
 {'text': 'Glimpses of Bengal',
  'name_as_written': 'horse',
  'category': 'Mammals',
  'common_english_name': 'Horse',
  'quotation': 'I would career away madly, like a wild horse, for very joy of my own speed!',
  'location': 'Letter 16: Shelidah, 31st Jaistha (June)1892 (line 1281)',
  'status': 'Verified',
  'occurrences': 1,
  'setting': 'India',
  'paratext_only': False,
  'remarks': 'Simile.'},
 {'text': 'Glimpses of Bengal',
  'name_as_written': 'lion',
  'category': 'Mammals',
  'common_english_name': 'Lion',
  'quotation': 'In the _Sakuntala_ of Kalidas there is a scene where Bharat, the infant son of King '
               'Dushyanta, is playing with a lion cub.',
  'location': 'Letter 25: Boalia, 18th November 1892 (line 1618)',
  'status': 'Verified',
  'occurrences': 1,
  'setting': 'India',
  'paratext_only': False,
  'remarks': "Recalls the scene in Kalidasa's Sakuntala where the boy Bharat plays with a lion cub."},
 {'text': 'Glimpses of Bengal',
  'name_as_written': 'bison',
  'category': 'Mammals',
  'common_english_name': 'Bison',
  'quotation': 'Under the jagged lower edges of the clouds there shone forth a blood-red glare, as through '
               'the eyes of a monstrous, sky-filling bison, with tossing mane and with head lowered to '
               'strike the earth in fury.',
  'location': 'Letter 22: Shazadpur, 27th June 1892 (line 1504)',
  'status': 'Verified',
  'occurrences': 1,
  'setting': 'India',
  'paratext_only': False,
  'remarks': 'Simile for a storm cloud.'},
