def summary():
    """Print category totals for the whole corpus and for each text."""
    print("Extraction of Indian Cultural Elements Using RAG: summary")
    print("=" * 60)
    nf = sum(len(v) for v in flora_RAG_extraction.values())
    na = sum(len(v) for v in fauna_RAG_extraction.values())
    print(f"Unique flora across the corpus: {nf}")
    for c in FLORA_CATEGORIES:
        print(f"   {c:<8} {len(flora_RAG_extraction[c]):>4}")
    print(f"Unique fauna across the corpus: {na}")
    for c in FAUNA_CATEGORIES:
        print(f"   {c:<8} {len(fauna_RAG_extraction[c]):>4}")
    print("-" * 60)
    for text, cats in FLORA_FAUNA_BY_TEXT.items():
        f = sum(len(cats[c]) for c in FLORA_CATEGORIES)
        a = sum(len(cats[c]) for c in FAUNA_CATEGORIES)
        amb = sum(1 for c in cats for x in cats[c] if x.endswith("[Ambiguous]"))
        print(f"{text:<28} flora {f:>3}  fauna {a:>3}  (ambiguous {amb})")
    print("-" * 60)
    print(f"Evidence records: {len(EVIDENCE)}")


if __name__ == "__main__":
    summary()
